#include <iostream>
#include <string>
#include "../include/url_parser.h"

int main(int argc, char* argv[]) {
    if (argc < 7) return 1;

    std::string scheme = argv[1];
    std::string host = argv[2];
    int port = std::stoi(argv[3]);
    std::string path = argv[4];
    std::string query = argv[5];
    std::string fragment = argv[6];

    url_parser::URL parser = url_parser::URL::from_components(
        scheme, host, port, path, query, fragment);

    std::cout << parser.scheme() << std::endl;
    std::cout << parser.host() << std::endl;
    std::cout << parser.port() << std::endl;
    std::cout << parser.path() << std::endl;
    std::cout << parser.query() << std::endl;
    std::cout << parser.fragment() << std::endl;
    std::cout << parser.to_string() << std::endl;
    std::cout << parser.is_valid() << std::endl;

    return 0;
}


